Problem:
A skiing resort has two methods of getting their customers up to their resort. They can either use a gondola, or a large bus. On average, a gondola can transport skiers and snowboarders at a rate of 20 people per minute whereas a large bus can transport at a rate of 5 people per minute. However, gondolas cost the resort a lot to maintain and at most 40% of the transportation methods implemented can be gondolas. Since large buses are easier to implement, there must be at least ten times more large buses than gondolas. If the manufacturer wants to move at least 500 customers every minute up the mountain, find the minimum transportation implementations that can be used.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "gondolas",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "large buses",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "gondolas",
     "coef": 1.0
    },
    {
     "var": "large buses",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "throughput",
    "terms": [
     {
      "var": "gondolas",
      "coef": 20.0
     },
     {
      "var": "large buses",
      "coef": 5.0
     }
    ],
    "sense": ">=",
    "rhs": 500.0
   },
   {
    "name": "gondola share limit",
    "terms": [
     {
      "var": "gondolas",
      "coef": 0.6
     },
     {
      "var": "large buses",
      "coef": -0.4
     }
    ],
    "sense": "<=",
    "rhs": 0.0
   },
   {
    "name": "bus to gondola ratio",
    "terms": [
     {
      "var": "large buses",
      "coef": 1.0
     },
     {
      "var": "gondolas",
      "coef": -10.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 79.0,
  "values": {
   "gondolas": 7.0,
   "large buses": 72.0
  },
  "binding": [
   "throughput"
  ],
  "slack": {
   "throughput": 0.0,
   "gondola share limit": 24.6,
   "bus to gondola ratio": 2.0
  },
  "shadow_prices": null,
  "limits": {
   "throughput": {
    "dropped_improves": true,
    "loosened_improves": false
   },
   "gondola share limit": {
    "dropped_improves": false,
    "loosened_improves": false
   },
   "bus to gondola ratio": {
    "dropped_improves": true,
    "loosened_improves": false
   }
  }
 }
}
